    uint64_t size;       // bytes hashed
    uint8_t buf[64];
    size_t buf_size;
} lzma_sha256_state;

void lzma_sha256_init(lzma_sha256_state *s);
void lzma_sha256_update(lzma_sha256_state *s, const uint8_t *buf, size_t size);
