#include "check.h"

uint32_t lzma_crc32_table[8][256];
uint32_t lzma_crc64_table[8][256];

void lzma_crc32_init(void)
{
    for (uint32_t b = 0; b < 256; b++) {
        uint32_t r = b;
        for (int i = 0; i < 8; i++)
            r = (r >> 1) ^ ((r & 1) ? UINT32_C(0xEDB88320) : 0);
        lzma_crc32_table[0][b] = r;
    }
    for (int s = 1; s < 8; s++)
        for (int b = 0; b < 256; b++)
            lzma_crc32_table[s][b] = (lzma_crc32_table[s-1][b] >> 8)
                    ^ lzma_crc32_table[0][lzma_crc32_table[s-1][b] & 0xFF];
}

void lzma_crc64_init(void)
{
    for (uint32_t b = 0; b < 256; b++) {
        uint64_t r = b;
        for (int i = 0; i < 8; i++)
            r = (r >> 1) ^ ((r & 1) ? UINT64_C(0xC96C5795D7870F42) : 0);
        lzma_crc64_table[0][b] = r;
    }
    for (int s = 1; s < 8; s++)
        for (int b = 0; b < 256; b++)
            lzma_crc64_table[s][b] = (lzma_crc64_table[s-1][b] >> 8)
                    ^ lzma_crc64_table[0][lzma_crc64_table[s-1][b] & 0xFF];
}

uint32_t lzma_crc32(const uint8_t *buf, size_t size, uint32_t crc)
{
    crc = ~crc;
    while (size != 0) {
        crc = lzma_crc32_table[0][(*buf++) ^ (crc & 0xFF)] ^ (crc >> 8);
        size--;
    }
    return ~crc;
}

uint64_t lzma_crc64(const uint8_t *buf, size_t size, uint64_t crc)
{
    crc = ~crc;
    while (size != 0) {
        crc = lzma_crc64_table[0][(*buf++) ^ (crc & 0xFF)] ^ (crc >> 8);
        size--;
    }
    return ~crc;
}

// SHA-256
static const uint32_t sha256_k[64] = {
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1,
    0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
    0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786,
    0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
    0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
    0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
    0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
    0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
    0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
};

static void sha256_transform(lzma_sha256_state *s, const uint8_t *buf)
{
    uint32_t w[64];
    for (int i = 0; i < 16; i++)
        w[i] = ((uint32_t)buf[i*4] << 24) | ((uint32_t)buf[i*4+1] << 16)
             | ((uint32_t)buf[i*4+2] << 8) | (uint32_t)buf[i*4+3];
    for (int i = 16; i < 64; i++) {
        uint32_t s0 = ((w[i-15] >> 7) | (w[i-15] << 25)) ^ ((w[i-15] >> 18) | (w[i-15] << 14)) ^ (w[i-15] >> 3);
        uint32_t s1 = ((w[i-2] >> 17) | (w[i-2] << 15)) ^ ((w[i-2] >> 19) | (w[i-2] << 13)) ^ (w[i-2] >> 10);
        w[i] = w[i-16] + s0 + w[i-7] + s1;
    }
    uint32_t a = s->state[0], b = s->state[1], c = s->state[2], d = s->state[3];
    uint32_t e = s->state[4], f = s->state[5], g = s->state[6], h = s->state[7];
    for (int i = 0; i < 64; i++) {
        uint32_t S1 = ((e >> 6) | (e << 26)) ^ ((e >> 11) | (e << 21)) ^ ((e >> 25) | (e << 7));
        uint32_t ch = (e & f) ^ (~e & g);
        uint32_t t1 = h + S1 + ch + sha256_k[i] + w[i];
        uint32_t S0 = ((a >> 2) | (a << 30)) ^ ((a >> 13) | (a << 19)) ^ ((a >> 22) | (a << 10));
        uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t t2 = S0 + maj;
        h = g; g = f; f = e; e = d + t1; d = c; c = b; b = a; a = t1 + t2;
    }
    s->state[0] += a; s->state[1] += b; s->state[2] += c; s->state[3] += d;
    s->state[4] += e; s->state[5] += f; s->state[6] += g; s->state[7] += h;
}

void lzma_sha256_init(lzma_sha256_state *s)
{
    s->state[0] = 0x6a09e667; s->state[1] = 0xbb67ae85;
    s->state[2] = 0x3c6ef372; s->state[3] = 0xa54ff53a;
    s->state[4] = 0x510e527f; s->state[5] = 0x9b05688c;
    s->state[6] = 0x1f83d9ab; s->state[7] = 0x5be0cd19;
    s->size = 0;
    s->buf_size = 0;
}

void lzma_sha256_update(lzma_sha256_state *s, const uint8_t *buf, size_t size)
{
    s->size += size;
    if (s->buf_size != 0) {
        size_t need = 64 - s->buf_size;
        size_t take = need < size ? need : size;
        for (size_t i = 0; i < take; i++) s->buf[s->buf_size + i] = buf[i];
        s->buf_size += take;
        buf += take;
        size -= take;
        if (s->buf_size == 64) {
            sha256_transform(s, s->buf);
            s->buf_size = 0;
        }
    }
    while (size >= 64) {
        sha256_transform(s, buf);
        buf += 64;
        size -= 64;
    }
    for (size_t i = 0; i < size; i++) s->buf[i] = buf[i];
    s->buf_size = size;
}

void lzma_sha256_finish(lzma_sha256_state *s, uint8_t out[32])
{
    uint64_t bits = s->size * 8;
    uint8_t pad = 0x80;
    lzma_sha256_update(s, &pad, 1);
    pad = 0;
    while (s->buf_size != 56)
        lzma_sha256_update(s, &pad, 1);
    uint8_t lenbuf[8];
    for (int i = 0; i < 8; i++)
        lenbuf[i] = (uint8_t)(bits >> (56 - 8*i));
    // append length manually without affecting s->size
    for (int i = 0; i < 8; i++) s->buf[s->buf_size++] = lenbuf[i];
    sha256_transform(s, s->buf);
    for (int i = 0; i < 8; i++) {
        out[i*4]   = (uint8_t)(s->state[i] >> 24);
        out[i*4+1] = (uint8_t)(s->state[i] >> 16);
        out[i*4+2] = (uint8_t)(s->state[i] >> 8);
        out[i*4+3] = (uint8_t)(s->state[i]);
    }
}

#ifndef XZ_LZMA_DECODER_H
#define XZ_LZMA_DECODER_H

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

#define LZMA_STATES 12
#define LZMA_POS_STATES_MAX 16
#define LZMA_MATCH_LEN_MIN 2
#define LZMA_MATCH_LEN_MAX 273
#define LZMA_DIST_STATES 4
#define LZMA_ALIGN_BITS 4
#define LZMA_ALIGN_SIZE 16
#define LZMA_LITERAL_CODERS_MAX 16
#define LZMA_LITERAL_CODER_SIZE 0x300
#define LZMA_PROBS_SIZE (1846 + (1 << 4) * LZMA_LITERAL_CODER_SIZE)

typedef struct {
    const uint8_t *in;
    size_t in_pos;
    size_t in_size;
    uint32_t range;
    uint32_t code;
    uint8_t init_bytes_left; // bytes still needed for init (5)
    bool init_done;
    bool corrupt;
} lzma_rc_dec;

// The LZMA probability model
typedef struct {
    uint16_t probs[LZMA_PROBS_SIZE]; // layout below
    uint32_t state;
    uint32_t rep0, rep1, rep2, rep3;
    uint32_t lc, lp, pb;
    uint32_t lp_mask, pb_mask;
    uint32_t literal_context_bits, literal_pos_mask;
} lzma_lzma_dec;

// Dictionary (circular)
typedef struct {
    uint8_t *buf;
    size_t size;    // dict size
    size_t pos;     // current write pos
    size_t full;    // how much history is valid (<= size)
    bool need_reset;
} lzma_dict;

typedef enum {
    LZMA_DEC_OK = 0,        // chunk/stream finished cleanly
    LZMA_DEC_NEED_INPUT,    // ran out of input mid-stream (caller decides: EOF error or refill)
    LZMA_DEC_CORRUPT,
    LZMA_DEC_UNSUPPORTED,
} lzma_dec_ret;

// offsets into probs[]
#define P_IS_MATCH 0
#define P_IS_REP (P_IS_MATCH + LZMA_STATES * LZMA_POS_STATES_MAX)
#define P_IS_REP_G0 (P_IS_REP + LZMA_STATES)
#define P_IS_REP_G1 (P_IS_REP_G0 + LZMA_STATES)
#define P_IS_REP_G2 (P_IS_REP_G1 + LZMA_STATES)
#define P_IS_REP_G0_LONG (P_IS_REP_G2 + LZMA_STATES)
#define P_POS_SLOT (P_IS_REP_G0_LONG + LZMA_STATES * LZMA_POS_STATES_MAX)
#define P_SPEC_POS (P_POS_SLOT + LZMA_DIST_STATES * 64)
#define P_ALIGN (P_SPEC_POS + 1 + 115)  // kNumFullDistances - kEndPosModelIndex = 114, +1
#define P_LEN_CHOICE (P_ALIGN + LZMA_ALIGN_SIZE)
#define P_LEN_CHOICE2 (P_LEN_CHOICE + 1)
#define P_LEN_LOW (P_LEN_CHOICE2 + 1)
#define P_LEN_MID (P_LEN_LOW + LZMA_POS_STATES_MAX * 8)
#define P_LEN_HIGH (P_LEN_MID + LZMA_POS_STATES_MAX * 8)
#define P_LITERAL (P_LEN_HIGH + 256)

void lzma_lzma_dec_reset(lzma_lzma_dec *d, uint32_t lc, uint32_t lp, uint32_t pb);
void lzma_rc_dec_init(lzma_rc_dec *rc);

// Decode exactly one LZMA chunk producing up to out_limit bytes into dict,
// reading compressed data from rc->in. If uncomp_size_known is false,
// decoding stops at end-of-stream marker (LZMA1 only).
// Returns LZMA_DEC_OK when the chunk ended properly (size reached or marker).
lzma_dec_ret lzma_lzma_decode(lzma_lzma_dec *d, lzma_rc_dec *rc, lzma_dict *dict,
        bool uncomp_size_known, uint64_t uncomp_size,
        bool eopm_allowed, bool *eopm_found, uint64_t *produced);

#endif

#include "lzma_decoder.h"

#define RC_TOP (1u << 24)
#define PROB_INIT 0x400
#define MOVE_BITS 5

void lzma_lzma_dec_reset(lzma_lzma_dec *d, uint32_t lc, uint32_t lp, uint32_t pb)
{
    d->lc = lc; d->lp = lp; d->pb = pb;
    d->lp_mask = (1u << lp) - 1;
    d->pb_mask = (1u << pb) - 1;
    for (size_t i = 0; i < LZMA_PROBS_SIZE; i++)
        d->probs[i] = PROB_INIT;
    d->state = 0;
    d->rep0 = d->rep1 = d->rep2 = d->rep3 = 0;
}

void lzma_rc_dec_init(lzma_rc_dec *rc)
{
    rc->range = 0xFFFFFFFF;
    rc->code = 0;
    rc->init_bytes_left = 5;
    rc->init_done = false;
    rc->corrupt = false;
}

static inline bool rc_read_byte(lzma_rc_dec *rc, uint32_t *b)
{
    if (rc->in_pos >= rc->in_size)
        return false;
    *b = rc->in[rc->in_pos++];
    return true;
}

// normalize: returns false if input exhausted
static inline bool rc_normalize(lzma_rc_dec *rc)
{
    if (rc->range < RC_TOP) {
        uint32_t b;
        if (!rc_read_byte(rc, &b)) {
            rc->corrupt = true;
            return false;
        }
        rc->range <<= 8;
        rc->code = (rc->code << 8) | b;
    }
    return true;
}

static inline int rc_bit(lzma_rc_dec *rc, uint16_t *prob, int *bit)
{
    if (!rc_normalize(rc))
        return -1;
    uint32_t bound = (rc->range >> 11) * (*prob);
    if (rc->code < bound) {
        rc->range = bound;
        *prob += (uint16_t)((0x800 - *prob) >> MOVE_BITS);
        *bit = 0;
    } else {
        rc->range -= bound;
        rc->code -= bound;
        *prob -= (uint16_t)(*prob >> MOVE_BITS);
        *bit = 1;
    }
    return 0;
}

static inline int rc_direct(lzma_rc_dec *rc, int nbits, uint32_t *out)
{
    uint32_t res = 0;
    for (int i = 0; i < nbits; i++) {
        if (!rc_normalize(rc))
            return -1;
        rc->range >>= 1;
        res <<= 1;
        if (rc->code >= rc->range) {
            rc->code -= rc->range;
            res |= 1;
        }
    }
    *out = res;
    return 0;
}

static inline int rc_bittree(lzma_rc_dec *rc, uint16_t *probs, int nbits, uint32_t *out)
{
    uint32_t sym = 1;
    for (int i = 0; i < nbits; i++) {
        int bit;
        if (rc_bit(rc, &probs[sym], &bit))
            return -1;
        sym = (sym << 1) | bit;
    }
    *out = sym - (1u << nbits);
    return 0;
}

static inline int rc_bittree_rev(lzma_rc_dec *rc, uint16_t *probs, int nbits, uint32_t *out)
{
    uint32_t sym = 1, res = 0;
    for (int i = 0; i < nbits; i++) {
        int bit;
        if (rc_bit(rc, &probs[sym], &bit))
            return -1;
        sym = (sym << 1) | bit;
        res |= (uint32_t)bit << i;
    }
    *out = res;
    return 0;
}

static inline size_t dict_avail_write(lzma_dict *dict)
{
    return dict->size - dict->pos;
}

static inline void dict_put(lzma_dict *dict, uint8_t b)
{
    dict->buf[dict->pos++] = b;
    if (dict->full < dict->pos)
        dict->full = dict->pos;
}

// copy match of len bytes at distance dist+1. Caller ensures validity.
// returns number of bytes actually copied (limited by remaining out space)
static inline int dict_repeat(lzma_dict *dict, uint32_t dist, uint32_t len,
        uint64_t *remaining)
{
    // dist is distance-1 (i.e. rep value). back position:
    size_t back;
    if (dist >= dict->full || dict->pos == 0 && dict->full == 0)
        return -1;
    if (dict->pos > dist)
        back = dict->pos - dist - 1;
    else
        back = dict->size - (dist - dict->pos) - 1;
    uint32_t n = 0;
    while (n < len && *remaining > 0) {
        uint8_t b = dict->buf[back++];
        if (back == dict->size)
            back = 0;
        dict_put(dict, b);
        if (dict->pos == dict->size && *remaining > 1) {
            // buffer full: caller must flush; we signal by returning early
        }
        n++;
        (*remaining)--;
        if (dict->pos == dict->size)
            break; // need flush; return partial
    }
    return (int)n;
}

lzma_dec_ret lzma_lzma_decode(lzma_lzma_dec *d, lzma_rc_dec *rc, lzma_dict *dict,
        bool uncomp_size_known, uint64_t uncomp_size,
        bool eopm_allowed, bool *eopm_found, uint64_t *produced)
{
    uint64_t remaining = uncomp_size_known ? uncomp_size : UINT64_MAX;
    *produced = 0;
    *eopm_found = false;

    // init range decoder
    if (!rc->init_done) {
        uint32_t b;
        while (rc->init_bytes_left > 0) {
            if (!rc_read_byte(rc, &b)) {
                return LZMA_DEC_NEED_INPUT;
            }
            if (rc->init_bytes_left == 5 && b != 0) {
                rc->corrupt = true;
                return LZMA_DEC_CORRUPT;
            }
            if (rc->init_bytes_left <= 4)
                rc->code = (rc->code << 8) | b;
            rc->init_bytes_left--;
        }
        rc->init_done = true;
    }

    while (remaining > 0) {
        if (dict->pos == dict->size)
            return LZMA_DEC_OK; // dict full; caller flushes and re-enters

        uint32_t pos_state = (uint32_t)(dict->pos + 0) & d->pb_mask;
        // note: pos state is based on total uncompressed position, not dict pos.
        // caller adjusts via d->pos_offset? We track separately below.
        (void)pos_state;
        break;
    }
    // We need total uncompressed position for pos states. Use a field.
    return LZMA_DEC_OK;
}

