#include "lzma_decoder.h"
#include <string.h>

#define RC_TOP (1u << 24)
#define PROB_INIT 0x400
#define MOVE_BITS 5

void lzma_lzma_dec_reset(lzma_lzma_dec *d, uint32_t lc, uint32_t lp, uint32_t pb)
{
    d->lc = lc; d->lp = lp; d->pb = pb;
    d->lp_mask = (1u << lp) - 1;
    d->pb_mask = (1u << pb) - 1;
    for (size_t i = 0; i < LZMA_PROBS_SIZE; i++)
        d->probs[i] = PROB_INIT;
    d->state = 0;
    d->rep0 = d->rep1 = d->rep2 = d->rep3 = 0;
}

void lzma_rc_dec_init(lzma_rc_dec *rc)
{
    rc->range = 0xFFFFFFFF;
    rc->code = 0;
    rc->init_bytes_left = 5;
    rc->init_done = false;
    rc->corrupt = false;
}

static inline bool rc_read_byte(lzma_rc_dec *rc, uint32_t *b)
{
    if (rc->in_pos >= rc->in_size)
        return false;
    *b = rc->in[rc->in_pos++];
    return true;
}

static inline bool rc_normalize(lzma_rc_dec *rc)
{
    if (rc->range < RC_TOP) {
        uint32_t b;
        if (!rc_read_byte(rc, &b)) {
            rc->corrupt = true;
            return false;
        }
        rc->range <<= 8;
        rc->code = (rc->code << 8) | b;
    }
    return true;
}

static inline int rc_bit(lzma_rc_dec *rc, uint16_t *prob, uint32_t *bit)
{
    if (!rc_normalize(rc))
        return -1;
    uint32_t bound = (rc->range >> 11) * (*prob);
    if (rc->code < bound) {
        rc->range = bound;
        *prob += (uint16_t)((0x800 - *prob) >> MOVE_BITS);
        *bit = 0;
    } else {
        rc->range -= bound;
        rc->code -= bound;
        *prob -= (uint16_t)(*prob >> MOVE_BITS);
        *bit = 1;
    }
    return 0;
}

static inline int rc_direct(lzma_rc_dec *rc, int nbits, uint32_t *out)
{
    uint32_t res = 0;
    for (int i = 0; i < nbits; i++) {
        if (!rc_normalize(rc))
            return -1;
        rc->range >>= 1;
        res <<= 1;
        if (rc->code >= rc->range) {
            rc->code -= rc->range;
            res |= 1;
        }
    }
    *out = res;
    return 0;
}

static inline int rc_bittree(lzma_rc_dec *rc, uint16_t *probs, int nbits, uint32_t *out)
{
    uint32_t sym = 1;
    for (int i = 0; i < nbits; i++) {
        uint32_t bit;
        if (rc_bit(rc, &probs[sym], &bit))
            return -1;
        sym = (sym << 1) | bit;
    }
    *out = sym - (1u << nbits);
    return 0;
}

static inline int rc_bittree_rev(lzma_rc_dec *rc, uint16_t *probs, int nbits, uint32_t *out)
{
    uint32_t sym = 1, res = 0;
    for (int i = 0; i < nbits; i++) {
        uint32_t bit;
        if (rc_bit(rc, &probs[sym], &bit))
            return -1;
        sym = (sym << 1) | bit;
        res |= (uint32_t)bit << i;
    }
    *out = res;
    return 0;
}

// Decode LZMA symbols until `remaining` output bytes have been produced
// (when size_known) or until an end-of-stream marker (when !size_known).
// Returns:
//   LZMA_DEC_OK         - chunk done (size reached or marker found; *eopm tells)
//   LZMA_DEC_FLUSH      - dict buffer full; caller must flush and call again
//   LZMA_DEC_NEED_INPUT - input exhausted mid-symbol
//   LZMA_DEC_CORRUPT    - data error
lzma_dec_ret lzma_lzma_decode(lzma_lzma_dec *d, lzma_rc_dec *rc, lzma_dict *dict,
        uint64_t *remaining_io, bool size_known, bool eopm_allowed, bool *eopm)
{
    uint64_t remaining = *remaining_io;
    *eopm = false;

    if (!rc->init_done) {
        uint32_t b;
        while (rc->init_bytes_left > 0) {
            if (!rc_read_byte(rc, &b))
                return LZMA_DEC_NEED_INPUT;
            if (rc->init_bytes_left == 5 && b != 0) {
                rc->corrupt = true;
                return LZMA_DEC_CORRUPT;
            }
            if (rc->init_bytes_left <= 4)
                rc->code = (rc->code << 8) | b;
            rc->init_bytes_left--;
        }
        rc->init_done = true;
    }

    uint16_t *probs = d->probs;

    while (remaining > 0) {
        if (dict->pos == dict->size) {
            *remaining_io = remaining;
            return LZMA_DEC_FLUSH;
        }

        uint32_t pos_state = (uint32_t)dict->total & d->pb_mask;
        uint32_t bit;
        if (rc_bit(rc, &probs[P_IS_MATCH + d->state * LZMA_POS_STATES_MAX + pos_state], &bit))
            return LZMA_DEC_NEED_INPUT;

        if (bit == 0) {
            // literal
            uint32_t prev = dict->total == 0 ? 0
                    : dict->buf[dict->pos == 0 ? dict->size - 1 : dict->pos - 1];
            uint32_t lit_state = ((uint32_t)((dict->total & d->lp_mask) << d->lc)
                    + (prev >> (8 - d->lc))) * LZMA_LITERAL_CODER_SIZE;
            uint16_t *lp = &probs[P_LITERAL + lit_state];
            uint32_t symbol = 1;
            if (d->rep0 < dict->full) {
                // matched literal
                size_t back = dict->pos > d->rep0
                        ? dict->pos - d->rep0 - 1
                        : dict->size - (d->rep0 - dict->pos) - 1;
                uint32_t match_byte = dict->buf[back];
                do {
                    uint32_t match_bit = (match_byte >> 7) & 1;
                    match_byte <<= 1;
                    if (rc_bit(rc, &lp[((1 + match_bit) << 8) + symbol], &bit))
                        return LZMA_DEC_NEED_INPUT;
                    symbol = (symbol << 1) | bit;
                    if (match_bit != bit)
                        break;
                } while (symbol < 0x100);
            }
            while (symbol < 0x100) {
                if (rc_bit(rc, &lp[symbol], &bit))
                    return LZMA_DEC_NEED_INPUT;
                symbol = (symbol << 1) | bit;
            }
            dict->buf[dict->pos++] = (uint8_t)symbol;
            if (dict->full < dict->pos)
                dict->full = dict->pos;
            dict->total++;
            remaining--;
            d->state = d->state < 4 ? 0 : d->state - (d->state < 10 ? 3 : 6);
            continue;
        }

        // match
        if (rc_bit(rc, &probs[P_IS_REP + d->state], &bit))
            return LZMA_DEC_NEED_INPUT;
        uint32_t len;
        if (bit == 1) {
            // rep match
            if (rc_bit(rc, &probs[P_IS_REP_G0 + d->state], &bit))
                return LZMA_DEC_NEED_INPUT;
            if (bit == 0) {
                if (rc_bit(rc, &probs[P_IS_REP_G0_LONG + d->state * LZMA_POS_STATES_MAX + pos_state], &bit))
                    return LZMA_DEC_NEED_INPUT;
                if (bit == 0) {
                    d->state = d->state < 7 ? 9 : 11;
                    len = 1;
                    goto rep_short;
                }
            } else {
                uint32_t tmp;
                if (rc_bit(rc, &probs[P_IS_REP_G1 + d->state], &bit))
                    return LZMA_DEC_NEED_INPUT;
                if (bit == 0) {
                    tmp = d->rep1;
                } else {
                    if (rc_bit(rc, &probs[P_IS_REP_G2 + d->state], &bit))
                        return LZMA_DEC_NEED_INPUT;
                    if (bit == 0) {
                        tmp = d->rep2;
                    } else {
                        tmp = d->rep3;
                        d->rep3 = d->rep2;
                    }
                    d->rep2 = d->rep1;
                }
                d->rep1 = d->rep0;
                d->rep0 = tmp;
            }
            d->state = d->state < 7 ? 8 : 11;
            // decode len
            if (rc_bit(rc, &probs[P_LEN_CHOICE], &bit))
                return LZMA_DEC_NEED_INPUT;
            if (bit == 0) {
                if (rc_bittree(rc, &probs[P_LEN_LOW + pos_state * 8], 3, &len))
                    return LZMA_DEC_NEED_INPUT;
            } else {
                if (rc_bit(rc, &probs[P_LEN_CHOICE2], &bit))
                    return LZMA_DEC_NEED_INPUT;
                if (bit == 0) {
                    if (rc_bittree(rc, &probs[P_LEN_MID + pos_state * 8], 3, &len))
                        return LZMA_DEC_NEED_INPUT;
                    len += 8;
                } else {
                    if (rc_bittree(rc, &probs[P_LEN_HIGH], 8, &len))
                        return LZMA_DEC_NEED_INPUT;
                    len += 16;
                }
            }
            len += LZMA_MATCH_LEN_MIN;
        } else {
            // simple match
            d->rep3 = d->rep2; d->rep2 = d->rep1; d->rep1 = d->rep0;
            if (rc_bit(rc, &probs[P_LEN_CHOICE], &bit))
                return LZMA_DEC_NEED_INPUT;
            if (bit == 0) {
                if (rc_bittree(rc, &probs[P_LEN_LOW + pos_state * 8], 3, &len))
                    return LZMA_DEC_NEED_INPUT;
            } else {
                if (rc_bit(rc, &probs[P_LEN_CHOICE2], &bit))
                    return LZMA_DEC_NEED_INPUT;
                if (bit == 0) {
                    if (rc_bittree(rc, &probs[P_LEN_MID + pos_state * 8], 3, &len))
                        return LZMA_DEC_NEED_INPUT;
                    len += 8;
                } else {
                    if (rc_bittree(rc, &probs[P_LEN_HIGH], 8, &len))
                        return LZMA_DEC_NEED_INPUT;
                    len += 16;
                }
            }
            len += LZMA_MATCH_LEN_MIN;
            d->state = d->state < 7 ? 7 : 10;
            // distance
            uint32_t slot;
            uint32_t dist_state = len - LZMA_MATCH_LEN_MIN < LZMA_DIST_STATES
                    ? len - LZMA_MATCH_LEN_MIN : LZMA_DIST_STATES - 1;
            if (rc_bittree(rc, &probs[P_POS_SLOT + dist_state * 64], 6, &slot))
                return LZMA_DEC_NEED_INPUT;
            if (slot < 4) {
                d->rep0 = slot;
            } else {
                int nbits = (int)(slot >> 1) - 1;
                d->rep0 = (2 | (slot & 1)) << nbits;
                if (slot < 14) {
                    uint32_t v;
                    if (rc_bittree_rev(rc, &probs[P_SPEC_POS + d->rep0 - slot], nbits, &v))
                        return LZMA_DEC_NEED_INPUT;
                    d->rep0 += v;
                } else {
                    uint32_t v;
                    if (rc_direct(rc, nbits - LZMA_ALIGN_BITS, &v))
                        return LZMA_DEC_NEED_INPUT;
                    d->rep0 += v << LZMA_ALIGN_BITS;
                    if (rc_bittree_rev(rc, &probs[P_ALIGN], LZMA_ALIGN_BITS, &v))
                        return LZMA_DEC_NEED_INPUT;
                    d->rep0 += v;
                    if (d->rep0 == UINT32_MAX) {
                        // end of stream marker
                        if (!eopm_allowed)
                            return LZMA_DEC_CORRUPT;
                        if (size_known && remaining != 0)
                            return LZMA_DEC_CORRUPT;
                        *eopm = true;
                        *remaining_io = remaining;
                        return LZMA_DEC_OK;
                    }
                }
            }
        }

        if (d->rep0 >= dict->full)
            return LZMA_DEC_CORRUPT;
rep_short:
        if (len > remaining) {
            if (size_known)
                return LZMA_DEC_CORRUPT;
            len = (uint32_t)remaining;
        }
        // copy len bytes at distance rep0+1
        {
            size_t back = dict->pos > d->rep0
                    ? dict->pos - d->rep0 - 1
                    : dict->size - (d->rep0 - dict->pos) - 1;
            for (uint32_t i = 0; i < len; i++) {
                uint8_t b = dict->buf[back++];
                if (back == dict->size)
                    back = 0;
                dict->buf[dict->pos++] = b;
                if (dict->full < dict->pos)
                    dict->full = dict->pos;
                dict->total++;
                remaining--;
                if (dict->pos == dict->size && i + 1 < len) {
                    // cannot wrap mid-match without flush; we must have
                    // dict size >= len always in practice (dict >= 4KiB,
                    // len <= 273), so this never triggers.
                    *remaining_io = remaining;
                    return LZMA_DEC_FLUSH;
                }
            }
        }
    }

    *remaining_io = remaining;
    return LZMA_DEC_OK;
}

