#ifndef XZ_XZDEC_H
#define XZ_XZDEC_H

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

// Check IDs
#define CHECK_NONE   0x00
#define CHECK_CRC32  0x01
#define CHECK_CRC64  0x04
#define CHECK_SHA256 0x0A

static inline size_t check_size(int id)
{
    switch (id) {
    case CHECK_NONE: return 0;
    case CHECK_CRC32: return 4;
    case CHECK_CRC64: return 8;
    case CHECK_SHA256: return 32;
    default: return 0;
    }
}

// Filter IDs
#define FILT_LZMA2    0x21
#define FILT_DELTA    0x03
#define FILT_X86      0x04
#define FILT_POWERPC  0x05
#define FILT_IA64     0x06
#define FILT_ARM      0x07
#define FILT_ARMTHUMB 0x08
#define FILT_SPARC    0x09
#define FILT_ARM64    0x0A
#define FILT_RISCV    0x0B

typedef struct {
    uint64_t id;
    uint8_t props[16];
    size_t props_size;
} filter_spec;

typedef struct {
    filter_spec filters[4];
    int nfilters;
    uint64_t comp_size;   // VLI_UNKNOWN if absent
    uint64_t uncomp_size;
    bool has_comp, has_uncomp;
    uint32_t header_size;
} block_header;

#define VLI_UNKNOWN UINT64_MAX
#define VLI_MAX 0x7FFFFFFFFFFFFFFFULL

#endif

