RangeEnc_EncodeBit(p, prob, bit):
  UInt32 ttt = *prob;
  UInt32 nb = (p->range >> 11) * ttt;
  if (bit == 0) { p->range = nb; ttt += (0x800 - ttt) >> 5; }
  else { p->low += nb; p->range -= nb; ttt -= ttt >> 5; }
  *prob = ttt;
  if (p->range < kTopValue) { p->range <<= 8; RangeEnc_ShiftLow(p); }

RangeEnc_ShiftLow:
  if ((UInt32)p->low < 0xFF000000 || (UInt32)(p->low >> 32) != 0) {
      Byte temp = p->cache;
      do { write(temp + (Byte)(p->low >> 32)); temp = 0xFF; } while (--p->cacheSize);
      p->cache = (Byte)(p->low >> 24);
  }
  p->cacheSize++;
  p->low = (UInt32)p->low << 8;

EncodeDirect(v, n): for i from n-1..0: range >>= 1; if ((v>>i)&1) low += range; if (range < top) { range <<= 8; ShiftLow; }

BitTree: standard.
Flush: for (i=0;i<5;i++) ShiftLow.
