#ifndef XZ_LZMA_ENCODER_H
#define XZ_LZMA_ENCODER_H

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

#define MATCH_LEN_MIN 2
#define MATCH_LEN_MAX 273
#define NUM_STATES 12
#define POS_STATES_MAX 16
#define DIST_STATES 4
#define DIST_SLOTS 64
#define DIST_MODEL_START 4
#define DIST_MODEL_END 14
#define FULL_DISTANCES 128
#define ALIGN_BITS 4
#define ALIGN_SIZE 16
#define LEN_LOW_SYMBOLS 8
#define LEN_MID_SYMBOLS 8
#define LEN_HIGH_SYMBOLS 256
#define LEN_SYMBOLS (LEN_LOW_SYMBOLS + LEN_MID_SYMBOLS + LEN_HIGH_SYMBOLS)
#define LITERAL_CODER_SIZE 0x300
#define RC_TOP (1u << 24)

// Match finder modes
#define MF_HC3 0x03
#define MF_HC4 0x04
#define MF_BT2 0x12
#define MF_BT3 0x13
#define MF_BT4 0x14

typedef struct {
    uint16_t len;
    uint32_t dist;   // 0-based (actual distance - 1)
} lzma_match;

// ---- Match finder ----
typedef struct {
    const uint8_t *buf;   // whole input
    size_t buf_size;
    uint32_t pos;         // current position (absolute), next byte to encode
    uint32_t dict_size;
    uint32_t cyclic_size; // dict_size + 1
    uint32_t hash_mask;
    uint32_t *hash;
    uint32_t *son;
    uint32_t depth;       // cut value
    uint32_t nice_len;
    int mode;             // MF_*
    uint32_t num_hash_bytes;
} lzma_mf;

void mf_init(lzma_mf *mf, const uint8_t *buf, size_t buf_size, uint32_t dict_size,
        uint32_t nice_len, uint32_t depth, int mode);
void mf_free(lzma_mf *mf);
// Find matches at current pos, then advance pos by 1 (inserting it).
// Returns matches (ascending len); count in *count.
uint32_t mf_find(lzma_mf *mf, lzma_match *matches);
void mf_skip(lzma_mf *mf, uint32_t num);
static inline uint32_t mf_avail(lzma_mf *mf)
{
    uint64_t a = (uint64_t)mf->buf_size - mf->pos;
    return a > MATCH_LEN_MAX ? MATCH_LEN_MAX : (uint32_t)a;
}

// ---- Range encoder ----
typedef struct {
    uint64_t low;
    uint32_t range;
    uint8_t cache;
    uint64_t cache_size;
    uint8_t *out;
    size_t out_pos;
} lzma_rc_enc;

void rc_enc_init(lzma_rc_enc *rc, uint8_t *out);
void rc_enc_flush(lzma_rc_enc *rc);
void rc_bit(lzma_rc_enc *rc, uint16_t *prob, uint32_t bit);
void rc_direct(lzma_rc_enc *rc, uint32_t value, uint32_t nbits);
void rc_bittree(lzma_rc_enc *rc, uint16_t *probs, uint32_t nbits, uint32_t value);
void rc_bittree_rev(lzma_rc_enc *rc, uint16_t *probs, uint32_t nbits, uint32_t value);

// ---- Price tables ----
#define MOVE_BITS 5
#define MOVE_REDUCING_BITS 4
#define BIT_PRICE_SHIFT_BITS 6
extern uint32_t rc_prices[2048 >> MOVE_REDUCING_BITS]; // kBitModelTotal >> reducing

void rc_prices_init(void);
#define RC_BIT_PRICE(prob, bit) \
    (rc_prices[(((prob) ^ ((uint32_t)(-(int32_t)(bit)) & 0x7FF)) >> MOVE_REDUCING_BITS)])
uint32_t rc_bittree_price(const uint16_t *probs, uint32_t nbits, uint32_t value);
uint32_t rc_bittree_rev_price(const uint16_t *probs, uint32_t nbits, uint32_t value);

#endif
